// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new C(address(this), 0); vm.stopPrank(); }
    function testFuzz_property(address actor, uint256 betLimit, uint256 value) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor != tx.origin ? false : true); // keep onlyRealPeople admissible: actor must be an EOA-style caller (fuzzed addresses are EOAs, so this holds)
        vm.deal(actor, 100 ether);
        // set an arbitrary bet limit as owner, then open the contract
        vm.prank(address(uint160(0xE0A)));
        c.AdjustBetAmounts(bound(betLimit, 0, 1 ether));
        vm.prank(address(uint160(0xE0A)));
        c.OpenToThePublic();
        uint256 amount = bound(value, 0, 1 ether);
        bool ok;
        vm.prank(actor);
        try c.wager{value: amount}() { ok = true; } catch { ok = false; }
        // Rule: once OpenToThePublic() has been called, an admissible wager with the exact
        // bet-limit value must succeed (and record the wager) for ANY actor.
        assertTrue(ok && c.hasPlayerWagered(actor));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
        owner = __invmut_eoa;
    }

    function testFuzz_property(address actor) public {
        vm.assume(uint160(actor) != 0);
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // onlyRealPeople: must be an EOA

        // owner opens the contract (allowed for every admissible state)
        vm.prank(owner, owner);
        c.OpenToThePublic();

        // any real person can now wager (betLimit is 0, so value must be 0)
        vm.deal(actor, 1 ether);
        vm.prank(actor, actor); // ensures tx.origin == msg.sender
        c.wager();

        assertTrue(c.hasPlayerWagered(actor));
    }
}

