// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner_ = address(uint160(0xE0A));
    address player = address(uint160(0xE0B));

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
        vm.deal(player, 1000 ether);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1 ether);
        vm.deal(owner_, 100 ether);
        vm.startPrank(owner_, owner_);
        c.OpenToThePublic();
        c.AdjustBetAmounts(amount);
        vm.stopPrank();

        vm.startPrank(player, player);
        bool wagered = false;
        try c.wager{value: amount}() {
            wagered = true;
        } catch {
            wagered = false;
        }
        vm.stopPrank();

        assertTrue(wagered && c.hasPlayerWagered(player), "exact-amount wager must be accepted after AdjustBetAmounts(amount)");
    }
}

