contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        uint256 cur = c.currentBetLimit();
        // ensure cur + amount overflows, so the mutant's += would revert
        require(cur > 0 && amount > type(uint256).max - cur);
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(c.AdjustBetAmounts.selector, amount));
        assert(ok && c.currentBetLimit() == amount);
    }
    receive() external payable {}
}

